const absolute = (p) => new URL(p, self.location.origin).href;
// A folder navigation ("/drive/") is stored under the file it serves.
const pageKey = (url) => absolute(url.pathname.endsWith('/') ? url.pathname + 'index.html' : url.pathname);
const isNavigation = (req) => req.mode === 'navigate' || (req.headers.get('accept') || '').includes('text/html');
const cacheable = (res) => !!res && res.ok && res.type === 'basic';

// HTML: the network first (so updates show), then the saved copy, then the offline page.
async function networkFirst(req, url) {
  const cache = await caches.open(CACHE);
  try {
    const res = await fetch(req);
    if (cacheable(res)) cache.put(pageKey(url), res.clone());
    return res;
  } catch (err) {
    return (await cache.match(pageKey(url))) || (await cache.match(absolute(OFFLINE))) || Response.error();
  }
}

// Static files: the saved copy first. A new CACHE version starts empty, so updates arrive with it.
async function cacheFirst(req) {
  const cache = await caches.open(CACHE);
  const hit = await cache.match(req.url);
  if (hit) return hit;
  const res = await fetch(req);
  if (cacheable(res)) cache.put(req.url, res.clone());
  return res;
}

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    // Tolerant: a file that cannot be fetched is reported and skipped; the rest still install.
    const results = await Promise.allSettled(PRECACHE.map(async (p) => {
      const res = await fetch(absolute(p), { cache: 'reload' });
      if (!cacheable(res)) throw new Error(p + ' answered ' + res.status);
      await cache.put(absolute(p), res);
    }));
    results.filter((r) => r.status === 'rejected').forEach((r) => console.warn('[slop sw] precache skipped:', r.reason.message));
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const name of await caches.keys()) {
      if (name.startsWith('slopographic-') && name !== CACHE) await caches.delete(name);
    }
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  const url = new URL(req.url);
  if (req.method !== 'GET' || url.origin !== self.location.origin) return;
  if (isNavigation(req)) event.respondWith(networkFirst(req, url));
  else if (STATIC.test(url.pathname)) event.respondWith(cacheFirst(req));
});
